import { mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const importer = fileURLToPath(import.meta.url);
const root = dirname(dirname(dirname(importer)));
const load = createRequire(import.meta.url);

function show(resolved) {
  return resolved.startsWith("/") || /^[A-Za-z]:\\/.test(resolved) ? relative(root, resolved).replaceAll("\\", "/") : resolved;
}

function describe(resolve, request) {
  try {
    return show(resolve(request));
  } catch (error) {
    return `${error.name} ${error.code}: ${error.message.replaceAll(importer, "<importer>")}`;
  }
}

const requests = [
  "fs",
  "node:fs",
  "node:test",
  "./data.json",
  "./data",
  "./index",
  "resolve-probe",
  "resolve-probe/data",
  "with-exports",
  "with-exports/feature",
  "with-exports/lib/helper",
  "with-main",
  "plain-index",
  "@scope/scoped",
  "./missing",
  "scriptc-corpus-missing-package",
  "",
  42,
];

// A package whose package.json starts with a byte order mark, written to a
// fresh directory and resolved by its absolute path: "main" is still read.
// The directory is named by its real path (the temporary directory is a
// symbolic link on macOS), so the resolved path is relative to it.
function resolveWithByteOrderMark() {
  const dir = realpathSync(mkdtempSync(join(tmpdir(), "scriptc-bom-")));
  try {
    const pkg = join(dir, "with-bom");
    mkdirSync(join(pkg, "lib"), { recursive: true });
    const manifest = JSON.stringify({ name: "with-bom", main: "lib/entry.js" });
    writeFileSync(join(pkg, "package.json"), "\uFEFF" + manifest);
    writeFileSync(join(pkg, "lib", "entry.js"), 'module.exports = "with-bom";\n');
    return relative(pkg, load.resolve(pkg));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

export function resolveAll(options = {}) {
  const resolve = options.resolve ?? load.resolve;
  const label = (request) => (typeof request === "string" ? JSON.stringify(request) : String(request));
  return [
    ...requests.map((request) => `call ${label(request)} -> ${describe((r) => load.resolve(r), request)}`),
    ...requests.slice(0, 4).map((request) => `value ${label(request)} -> ${describe(resolve, request)}`),
    `options ${describe((r) => load.resolve(r, {}), "with-main")}`,
    `byte order mark -> ${resolveWithByteOrderMark()}`,
  ];
}
